"use client";

import { useState } from "react";
import { useRouter } from "next/navigation";
import PocketBase from "pocketbase";
import { Button } from "@/components/ui/button";

export default function CrearPropuesta() {
  const router = useRouter();
  const pb = new PocketBase("http://127.0.0.1:8090");

  const [form, setForm] = useState({
    Titulo_Salida: "",
    Como_Llegar: "",
    Cuanto_Dura: "",
    Que_Llevar: [] as string[],
  });

  const handleChange = (e: React.ChangeEvent<HTMLInputElement | HTMLTextAreaElement>) => {
    const { name, value } = e.target;
    setForm(prev => ({
      ...prev,
      [name]: value
    }));
  };

  const handleQueLlevar = (e: React.ChangeEvent<HTMLInputElement>) => {
    const { value } = e.target;
    setForm(prev => ({
      ...prev,
      Que_Llevar: value.split(",").map(item => item.trim())
    }));
  };

  const handleSubmit = async () => {
    try {
      // Crear nueva propuesta en PocketBase
      await pb.collection("Salidas_Alumnos").create({
        Titulo_Salida: form.Titulo_Salida,
        Como_Llegar: form.Como_Llegar,
        Cuanto_Dura: form.Cuanto_Dura,
        Que_Llevar: form.Que_Llevar
      });

      // 🔹 Redirigir a la página principal con el parámetro para la notificación
      router.push("/?newProposal=true");

    } catch (error) {
      console.error("Error al crear propuesta:", error);
      alert("No se pudo crear la propuesta. Revisa la consola.");
    }
  };

  return (
    <div className="min-h-screen bg-background p-4 md:p-8 max-w-2xl mx-auto">
      <h1 className="text-3xl font-bold mb-6 text-center">Crear Nueva Propuesta</h1>

      <div className="space-y-4">
        <div>
          <label className="block mb-1 font-semibold">Título de la Salida</label>
          <input
            type="text"
            name="Titulo_Salida"
            value={form.Titulo_Salida}
            onChange={handleChange}
            className="w-full p-2 border rounded"
          />
        </div>

        <div>
          <label className="block mb-1 font-semibold">Cómo llegar</label>
          <textarea
            name="Como_Llegar"
            value={form.Como_Llegar}
            onChange={handleChange}
            className="w-full p-2 border rounded"
          />
        </div>

        <div>
          <label className="block mb-1 font-semibold">Cuánto dura</label>
          <input
            type="text"
            name="Cuanto_Dura"
            value={form.Cuanto_Dura}
            onChange={handleChange}
            className="w-full p-2 border rounded"
          />
        </div>

        <div>
          <label className="block mb-1 font-semibold">Qué llevar (separado por comas)</label>
          <input
            type="text"
            name="Que_Llevar"
            value={form.Que_Llevar.join(", ")}
            onChange={handleQueLlevar}
            className="w-full p-2 border rounded"
          />
        </div>

        <Button
          size="lg"
          className="w-full bg-[oklch(0.65_0.15_210)] text-white font-bold py-3"
          onClick={handleSubmit}
        >
          Crear Propuesta
        </Button>
      </div>
    </div>
  );
}